function isOwnerAccount(u){if(!u)return false;var e=(u.gmail||'').toLowerCase().trim(),r=String(u.rblxUserId||'').trim();return OWNER_CONFIG.emails.indexOf(e)!==-1||OWNER_CONFIG.robloxIds.indexOf(r)!==-1||u.isOwner===true;}
