function renderShopCheckout(){var cart=currentUser.shopCart||[];if(cart.length===0){setTimeout(function(){setShopTab('cart');},0);return '<p>Cart empty</p>';}var tM=0,tC=0;cart.forEach(function(it){tM+=(it.priceMoney||0);tC+=(it.priceCoins||0);});var itemsHtml=cart.map(function(it){return '<li>'+escapeHtml(it.name)+' — ₱'+(it.priceMoney||0).toLocaleString()+(it.priceCoins?' / 🪙 '+it.priceCoins.toLocaleString():'')+'</li>';}).join(''),monthly=checkoutState.paylaterTerm>0?(tM/checkoutState.paylaterTerm).toFixed(2):0,buyerName=currentUser.name||currentUser.displayName||'',buyerNumber=currentUser.number||'',needCoins=tC||0,haveCoins=currentUser.points||0,enough=(isOwnerAccount(currentUser)||haveCoins>=needCoins);var h='<div class="checkout-box"><h3>🛒 Order Summary</h3><ul style="padding-left:20px">'+itemsHtml+'</ul><div style="font-size:1.2rem;font-weight:900;color:#8b5cf6;margin-top:10px">Total: ₱'+tM.toLocaleString()+(tC?' / 🪙 '+tC.toLocaleString():'')+'</div></div>';h+='<div class="checkout-box"><h3>📍 Shipping Information</h3>';h+='<label>👤 Name <span style="color:#28a745;font-size:.72rem">⚙️ AUTO</span></label><input type="text" id="chkName" value="'+escapeHtml(buyerName)+'" readonly style="width:100%;padding:10px;border:1px solid #a7f3d0;border-radius:6px;background:#e8f8f0;color:#065f46;font-weight:bold">';h+='<label>📱 Number <span style="color:#28a745;font-size:.72rem">⚙️ AUTO</span></label><input type="text" id="chkNumber" value="'+escapeHtml(buyerNumber)+'" readonly style="width:100%;padding:10px;border:1px solid #a7f3d0;border-radius:6px;background:#e8f8f0;color:#065f46;font-weight:bold">';if(!buyerName||!buyerNumber)h+='<div style="background:#f8d7da;padding:8px;border-radius:4px;color:#721c24;font-size:.8rem;margin-top:8px">⚠️ Missing Name/Number in profile.</div>';h+='<label>🏠 Address <span style="color:#dc3545;font-size:.72rem">✍️ BUYER</span></label><input type="text" id="chkAddress" placeholder="House #, Street, City" style="width:100%;padding:10px;border:1px solid #a2a9b1;border-radius:6px">';h+='<label>📮 Postal <span style="color:#dc3545;font-size:.72rem">✍️ BUYER</span></label><input type="text" id="chkPostal" placeholder="e.g. 1000" style="width:100%;padding:10px;border:1px solid #a2a9b1;border-radius:6px"></div>';h+='<div class="checkout-box"><h3>💳 Payment Options</h3>';h+='<label style="display:flex;align-items:center;gap:10px;padding:12px;background:#fff3cd;border:2px solid #ffeeba;border-radius:8px;margin-bottom:10px"><input type="checkbox" id="chkBarrow" '+(checkoutState.barrow?'checked':'')+' onchange="checkoutState.barrow=this.checked" style="width:20px;height:20px"><div><b>📦 Barrow for 7 Days</b> <span style="background:#f59e0b;color:#fff;padding:2px 6px;border-radius:3px;font-size:.65rem">OPTIONAL</span></div></label>';h+='<label style="display:flex;align-items:center;gap:10px;padding:12px;background:#f3e8ff;border:2px solid #c4b5fd;border-radius:8px;margin-bottom:10px"><input type="checkbox" id="chkPayLater" '+(checkoutState.paylater?'checked':'')+' onchange="togglePayLater(this.checked)" style="width:20px;height:20px"><div><b>💳 XDRGPayLater</b> <span style="background:#8b5cf6;color:#fff;padding:2px 6px;border-radius:3px;font-size:.65rem">OPTIONAL</span></div></label>';if(checkoutState.paylater){h+='<div style="background:#f3e8ff;border:1px solid #c4b5fd;border-radius:6px;padding:12px;margin-bottom:10px"><div style="font-weight:bold;color:#8b5cf6;margin-bottom:8px">Choose Term:</div><div class="paylater-opts"><div class="paylater-opt '+(checkoutState.paylaterTerm===1?'active':'')+'" onclick="setPayLaterTerm(1)">1 Month</div><div class="paylater-opt '+(checkoutState.paylaterTerm===6?'active':'')+'" onclick="setPayLaterTerm(6)">6 Months</div><div class="paylater-opt '+(checkoutState.paylaterTerm===12?'active':'')+'" onclick="setPayLaterTerm(12)">12 Months</div></div>'+(checkoutState.paylaterTerm>0?'<div style="font-size:.85rem;margin-top:8px">💵 Monthly: <b>₱'+monthly+'</b></div>':'')+'</div>';}h+='<h4 style="color:#8b5cf6">Payment Method:</h4><div class="logistics-opts">';h+='<div class="logistics-opt '+(checkoutState.payment==='GCash'?'active':'')+'" onclick="setCheckoutPayment(\'GCash\')">'+LOGOS.GCash+'<span>GCash</span><span style="font-size:.65rem;color:#28a745">⚙️ Auto-pay</span></div>';h+='<div class="logistics-opt '+(checkoutState.payment==='Maya'?'active':'')+'" onclick="setCheckoutPayment(\'Maya\')">'+LOGOS.Maya+'<span>Maya</span><span style="font-size:.65rem;color:#28a745">⚙️ Auto-pay</span></div>';h+='<div class="logistics-opt '+(checkoutState.payment==='COD'?'active':'')+'" onclick="setCheckoutPayment(\'COD\')">'+LOGOS.COD+'<span>COD</span><span style="font-size:.65rem;color:#856404">🚚 Pay at door</span></div></div>';if(checkoutState.payment==='GCash'||checkoutState.payment==='Maya'){h+='<div style="margin-top:12px;padding:14px;background:#e8f8f0;border:2px solid #a7f3d0;border-radius:8px;font-size:.85rem;color:#065f46"><div style="font-weight:bold">⚙️ AUTO-PAY '+checkoutState.payment+'</div><div>💰 Coins: '+needCoins.toLocaleString()+' 🪙</div><div>💵 Cash: ₱'+tM.toLocaleString()+'</div><div>👤 '+escapeHtml(buyerName)+'</div><div>📱 '+escapeHtml(buyerNumber)+'</div>'+(enough?'<div style="padding:8px;background:#28a745;color:#fff;border-radius:4px;font-weight:bold;text-align:center;margin-top:8px">✅ Auto-processed on submit</div>':'<div style="padding:8px;background:#dc3545;color:#fff;border-radius:4px;font-weight:bold;text-align:center;margin-top:8px">❌ Not enough coins (need '+needCoins.toLocaleString()+')</div>')+'</div>';}else{h+='<div style="margin-top:12px;padding:14px;background:#fff3cd;border:2px solid #ffeeba;border-radius:8px;font-size:.85rem;color:#856404"><div style="font-weight:bold">🚚 CASH ON DELIVERY</div><div>Pay ₱'+tM.toLocaleString()+' to delivery man at your home.</div></div>';}h+='</div>';h+='<div style="display:flex;gap:10px;margin-top:16px"><button class="btn-save" style="flex:1;background:#6c757d;padding:14px" onclick="setShopTab(\'cart\')">← Back</button><button class="btn-claim" style="flex:2;background:linear-gradient(135deg,#28a745,#10b981);padding:16px;font-weight:900;margin-top:0" onclick="submitXdrgOrder()">💳 Place Order</button></div>';return h;}
async function submitXdrgOrder(){if(!currentUser)return;var cart=currentUser.shopCart||[];if(cart.length===0){showToast("❌ Cart empty","error");return;}var name=(currentUser.name||currentUser.displayName||'').trim(),num=(currentUser.number||'').trim(),addr=((document.getElementById('chkAddress')||{}).value||'').trim(),postal=((document.getElementById('chkPostal')||{}).value||'').trim();if(!name||!num){showToast("❌ Missing profile Name/Number","error");return;}if(!addr){showToast("❌ Fill Address","error");return;}if(!postal){showToast("❌ Fill Postal Code","error");return;}if(checkoutState.paylater&&checkoutState.paylaterTerm===0){showToast("❌ Choose PayLater term","error");return;}var tM=0,tC=0;cart.forEach(function(it){tM+=(it.priceMoney||0);tC+=(it.priceCoins||0);});if(checkoutState.payment==='GCash'||checkoutState.payment==='Maya'){if(!isOwnerAccount(currentUser)){if((currentUser.points||0)<tC){showToast("❌ Not enough coins: need "+tC.toLocaleString(),"error");return;}currentUser.points-=tC;}}var orderId="XDRG-ORD-"+Date.now().toString().slice(-8),payStatus=(checkoutState.payment==='GCash'||checkoutState.payment==='Maya')?'Paid-Online':'Pending-COD',order={id:orderId,userId:String(currentUser.rblxUserId),userName:currentUser.username||currentUser.name,items:cart,totalMoney:tM,totalCoins:tC,shipping:{name:name,number:num,address:addr,postal:postal},barrow:checkoutState.barrow,paylater:checkoutState.paylater,paylaterTerm:checkoutState.paylaterTerm,paylaterMonthly:checkoutState.paylaterTerm>0?(tM/checkoutState.paylaterTerm).toFixed(2):0,logistics:checkoutState.logistics||'J&T',payment:checkoutState.payment,paymentStatus:payStatus,status:'Pending',orderIdText:'',addressProcess:'',timestamp:Date.now()};currentUser.shopCart=[];saveUserData();updateUserStatusHeader();var orders=getAllShopOrders();orders.push(order);saveAllShopOrders(orders);try{await fetch(FIREBASE_BASE_URL+'/xdrg_shop/orders/'+orderId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(order)});var nid="SHOP-ORDER-"+Date.now(),payMsg=checkoutState.payment==='COD'?('🚚 COD ₱'+tM.toLocaleString()):('✅ Paid ₱'+tM.toLocaleString()+' via '+checkoutState.payment);await fetch(FIREBASE_BASE_URL+'/owner_alerts/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:'🛒 New Order — '+checkoutState.payment,message:name+' placed '+orderId+'\n'+payMsg+'\nShip: '+addr+', '+postal+'\nNum: '+num,timestamp:Date.now(),isShopOrder:true,orderId:orderId})});}catch(e){}showToast('✅ Order placed! '+orderId,'success');if(checkoutState.payment==='GCash'||checkoutState.payment==='Maya')setTimeout(function(){showToast('💸 Auto-paid ₱'+tM.toLocaleString(),'success');},1600);else setTimeout(function(){showToast('🚚 Pay ₱'+tM.toLocaleString()+' on delivery','info');},1600);setTimeout(triggerConfetti,400);sfxCoin();checkoutState={paylater:false,paylaterTerm:0,logistics:'J&T',payment:'COD',barrow:false};setShopTab('orders');}
function renderShopOrders(){var my=getAllShopOrders().filter(function(o){return String(o.userId)===String(currentUser.rblxUserId);});if(my.length===0)return '<div class="empty-state"><div class="icon">📋</div><p>No orders yet.</p></div>';var h='';my.slice().reverse().forEach(function(o){var items=o.items.map(function(it){return escapeHtml(it.name);}).join(', '),sc=o.status==='Pending'?'status-pending':(o.status==='Cancelled'?'status-unsuccessful':'status-successful');h+='<div class="order-card"><div class="oc-header"><div class="oc-id">'+escapeHtml(o.orderIdText||o.id)+'</div><span class="status-badge '+sc+'">'+escapeHtml(o.status)+'</span></div><div class="oc-info"><div><b>Items:</b> '+items+'</div><div><b>Total:</b> ₱'+(o.totalMoney||0).toLocaleString()+(o.totalCoins?' / 🪙 '+o.totalCoins.toLocaleString():'')+'</div><div><b>Ship:</b> '+escapeHtml(o.shipping.name)+', '+escapeHtml(o.shipping.number)+'</div><div><b>Address:</b> '+escapeHtml(o.shipping.address)+', '+escapeHtml(o.shipping.postal)+'</div><div><b>Logistics:</b> '+escapeHtml(o.logistics)+'</div><div><b>Payment:</b> '+escapeHtml(o.payment)+(o.paylater?' (PayLater '+o.paylaterTerm+'mo)':'')+(o.barrow?' + Barrow':'')+'</div>'+(o.paymentStatus?'<div><b>Pay Status:</b> '+escapeHtml(o.paymentStatus)+'</div>':'')+(o.orderIdText?'<div><b>Owner ID:</b> '+escapeHtml(o.orderIdText)+'</div>':'')+(o.addressProcess?'<div><b>Address Process:</b> '+escapeHtml(o.addressProcess)+'</div>':'')+'<div><b>Placed:</b> '+new Date(o.timestamp).toLocaleString()+'</div></div>'+(o.status==='Pending'?'<button class="btn-danger" style="width:100%;margin-top:10px" onclick="cancelXdrgOrder(\''+o.id+'\')">❌ Cancel</button>':'')+'</div>';});return h;}
function addToCart(pid){if(!currentUser){showToast("❌ Login","error");return;}var ps=getAllShopProducts(),p=null;for(var i=0;i<ps.length;i++){if(ps[i].id===pid){p=ps[i];break;}}if(!p){showToast("❌ Not found","error");return;}if(!currentUser.shopCart)currentUser.shopCart=[];for(var j=0;j<currentUser.shopCart.length;j++){if(currentUser.shopCart[j].id===pid){showToast("Already in cart","info");return;}}currentUser.shopCart.push({id:p.id,name:p.name,priceMoney:p.priceMoney||0,priceCoins:p.priceCoins||0,image:p.image||'',category:p.category||'',qty:1});saveUserData();renderXdrgShop();showToast('✅ Added!','success');}
function buyNow(pid){if(!currentUser){showToast("❌ Login","error");return;}var ps=getAllShopProducts(),p=null;for(var i=0;i<ps.length;i++){if(ps[i].id===pid){p=ps[i];break;}}if(!p){showToast("❌ Not found","error");return;}if(!currentUser.shopCart)currentUser.shopCart=[];var ex=false;for(var j=0;j<currentUser.shopCart.length;j++){if(currentUser.shopCart[j].id===pid){ex=true;break;}}if(!ex){currentUser.shopCart.push({id:p.id,name:p.name,priceMoney:p.priceMoney||0,priceCoins:p.priceCoins||0,image:p.image||'',category:p.category||'',qty:1});saveUserData();}checkoutState={paylater:false,paylaterTerm:0,logistics:'J&T',payment:'COD',barrow:false};shopTab='checkout';renderXdrgShop();showToast('⚡ Ready','success');}
function removeFromCart(pid){if(!currentUser)return;currentUser.shopCart=(currentUser.shopCart||[]).filter(function(x){return x.id!==pid;});saveUserData();renderXdrgShop();showToast('Removed','info');}
function togglePayLater(on){checkoutState.paylater=on;if(!on)checkoutState.paylaterTerm=0;renderXdrgShop();}
function setPayLaterTerm(t){checkoutState.paylaterTerm=t;renderXdrgShop();}
function setCheckoutLogistics(l){checkoutState.logistics=l;renderXdrgShop();}
function setCheckoutPayment(p){checkoutState.payment=p;renderXdrgShop();}
function cancelXdrgOrder(oid){if(!currentUser)return;if(!confirm("Cancel?"))return;var o=getAllShopOrders(),ix=-1;for(var i=0;i<o.length;i++){if(o[i].id===oid){ix=i;break;}}if(ix===-1)return;if(o[ix].status!=='Pending'){showToast("Cannot cancel","error");return;}o[ix].status='Cancelled';saveAllShopOrders(o);fetch(FIREBASE_BASE_URL+'/xdrg_shop/orders/'+oid+'/status.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify('Cancelled')}).catch(function(){});renderXdrgShop();showToast('✅ Cancelled','success');}
